function identity(a, b) {
  return a * a + 2 * a * b + b * b;
}

function max(a, b) {
  if (a > b) {
    return a;
  }
  return b;
}

function repeat(mot, n) {
  var resultat = "";
  for (var i = 0; i < n; i++) {
    resultat += mot;
  }
  return resultat;
}

identity(2, 3)     // 25
max(4, 9)          // 9
repeat("ha", 3)    // "hahaha"

function estEgal(t1, t2) {
  if (t1.length !== t2.length) {
    return false;
  }
  for (var i = 0; i < t1.length; i++) {
    if (t1[i] !== t2[i]) {
      return false;
    }
  }
  return true;
}

estEgal([1, 2, 3], [1, 2, 3])  // true
estEgal([1, 2, 3], [1, 2])     // false
estEgal([1, 2, 3], [1, 2, 4])  // false

function Etudiant(nom) {
  this.nom = nom;
  this.travailler = function () {
    if (this.nom === "Ndiaye") {
      console.log("Ndiaye se met au travail");
    }
  };
  this.seReposer = function () {
    if (this.nom === "Nama") {
      console.log("Nama est au repos");
    }
  };
}

var e1 = new Etudiant("Ndiaye");
e1.travailler();   // affiche : Ndiaye se met au travail

var e2 = new Etudiant("Diop");
e2.seReposer();    // n'affiche rien (le nom n'est pas Nama)
